effect.shader:
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

vec3 amostrar(vec2 uv, vec2 dir, float len) {
    vec3 soma = vec3(0.0);
    float pt = 0.0;
    for (int i = 0; i <= 32; i++) {
        float t = float(i) / 32.0;
        float w = pow(1.0 - t, 1.5);
        vec3 c = texture(inputImg, uv + dir * len * t).rgb;
        // o parâmetro len vem da chamada abaixo

        float l = dot(c, LUMA);
        float k = smoothstep(threshold, threshold + 0.1, l);
        soma += c * k * w;
        pt += w;
    }
    return soma / pt;
}

void main() {
    vec4 orig = texture(inputImg, acScreenNorm);
    int n = clamp(int(points), 2, 8);
    float base = radians(rotation);
    vec3 somaStreak = vec3(0.0);
    for (int i = 0; i < 8; i++) {
        if (i >= n) break;
        float ang = base + 3.14159 * float(i) / float(n);
        vec2 dir = vec2(cos(ang), sin(ang));
        dir.x /= acAspect;
        somaStreak += amostrar(acScreenNorm, dir, reach) + amostrar(acScreenNorm, -dir, reach);
    }
    fragColor = vec4(orig.rgb + somaStreak * intensity / float(n), orig.a);
}
